// Synthetic reports only. No customer files or real order identifiers belong in the repository.
export const cnpj='00000000000100';
export function report({order='900001',unit='8,56',quantity=6,total='51,36',cnpjValue=cnpj,status='FATURADO',date='28/10/2026',description='PRODUTO TESTE FRASCO 120 ML XAROPE',requested=total}={}){return ['PEDIDO MERCADO FARMA: '+order,'PEDIDO EXTERNO: 800001','DADOS DO PEDIDO','CNPJ: '+cnpjValue,'Status do Pedido: '+status+' Data Solicitacao: '+date,'N DA NOTA FISCAL: 700001 Emissao da Nota Fiscal: '+date,'TOTAL DO PEDIDO: R$ '+requested,'TOTAL ATENDIDO: R$ '+total,'TOTAL FATURADO: R$ '+total,'ITENS','N EAN DESCRICAO SOLICITADOS ATENDIDOS CANCELADOS PRECO UNIT. PRECO TOTAL SITUACAO',`1 7890000000001 ${description} ${quantity} ${quantity} 0 ${unit} ${total} Faturado`,`TOTAL ${quantity} ${quantity} 0 ${unit} ${total}`].join('\n');}
export function pdfBuffer(text){const escape=s=>s.replaceAll('\\','\\\\').replaceAll('(','\\(').replaceAll(')','\\)'),stream=text.split('\n').map((line,i)=>`BT /F1 9 Tf 15 ${570-i*25} Td (${escape(line)}) Tj ET`).join('\n'),objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`];let out='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(Buffer.byteLength(out));out+=`${i+1} 0 obj\n${o}\nendobj\n`;});const xref=Buffer.byteLength(out);out+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(out);}
export const file=(opts={},name='pedido.pdf')=>({name,mimeType:'application/pdf',buffer:pdfBuffer(report(opts))});
